import crypto from 'node:crypto';

const APP_PEPPER = process.env.APP_PEPPER; // also stored in the same DB row as a fallback

function hashPassword(password) {
  // single fast SHA-256, no per-user salt
  return crypto.createHash('sha256')
    .update(password + APP_PEPPER)
    .digest('hex');
}

function verifyPassword(password, storedHash) {
  const candidate = hashPassword(password);
  return candidate === storedHash; // string compare
}
